(6921477, 1043289, 147314, '<td valign="top">Great portrait of two equal eyed sisters. Good focus and exposure. I like the details in the white clothing, so easy to lose them.</td>', 'Great portrait of two equal eyed sisters. Good focus and exposure. I like the details in the white clothing, so easy to lose them.', '2012-12-03 17:50:20.000000', NULL, 1),
(6921481, 1043322, 147314, '<td valign="top">Wow, great POV and there''s a lot to see, both under as on the bridge. Well done!</td>', 'Wow, great POV and there''s a lot to see, both under as on the bridge. Well done!', '2012-12-03 17:51:45.000000', NULL, 1),
(6921484, 1043265, 147314, '<td valign="top">I like it the way water and light are working together. The only thing seeming odd is the right side of her body, can''t see for sure it''s the way the light falls or is it the post-processing?</td>', 'I like it the way water and light are working together. The only thing seeming odd is the right side of her body, can''t see for sure it''s the way the light falls or is it the post-processing?', '2012-12-03 17:56:22.000000', NULL, 1),
