INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6923254, 1042300, 86218, '<td valign="top">Well composed. Good still life. Works for me</td>', 'Well composed. Good still life. Works for me', '2012-12-05 00:57:08.000000', NULL, 1),
(6923256, 1042914, 86218, '<td valign="top">Beautiful light, Bokeh and sharp. Whish he was sitting on a more natural perch. Great shot none the less. Love those curling feathers coming up.</td>', 'Beautiful light, Bokeh and sharp. Whish he was sitting on a more natural perch. Great shot none the less. Love those curling feathers coming up.', '2012-12-05 00:58:58.000000', NULL, 1),
(6923262, 1042864, 86218, '<td valign="top">Nice use of lines here both on the vertical as well as the horizontal. Nicely timed with the splash of waves. The heads of the people are breaking the horizon just just and wonder what it would have done for the image to have dipped slightly lower..Just slightly.<br/>One thing I would change in this shot is to increase the contrast on this shot. Tones are more grey and flat. Maybe that''s what you were trying to stay with not sure. Great image none the less and portrayes life on the piers for fishermen well by using the simple comp rules.</td>', 'Nice use of lines here both on the vertical as well as the horizontal. Nicely timed with the splash of waves. The heads of the people are breaking the horizon just just and wonder what it would have done for the image to have dipped slightly lower..Just slightly.One thing I would change in this shot is to increase the contrast on this shot. Tones are more grey and flat. Maybe that''s what you were trying to stay with not sure. Great image none the less and portrayes life on the piers for fishermen well by using the simple comp rules.', '2012-12-05 01:03:20.000000', NULL, 1),
(6923272, 1043224, 86218, '<td valign="top">Wow. Lovely shot and certainly golden Hour. This would do great in the proportian challenge as well 8</td>', 'Wow. Lovely shot and certainly golden Hour. This would do great in the proportian challenge as well 8', '2012-12-05 01:07:21.000000', NULL, 1),
