(6925291, 1042702, 23484, '<td valign="top">Very nicely composed.</td>', 'Very nicely composed.', '2012-12-06 19:06:40.000000', NULL, 1),
(6925336, 1043335, 3102, '<td valign="top">There''s good potential here, but I would have cropped in MUCH tighter on the player making the catch.  The crowd doesn''t really add to the shot, and the opposing player is far enough out of the frame that I would have cropped him out, too.</td>', 'There''s good potential here, but I would have cropped in MUCH tighter on the player making the catch.  The crowd doesn''t really add to the shot, and the opposing player is far enough out of the frame that I would have cropped him out, too.', '2012-12-06 20:57:35.000000', NULL, 1),
(6925351, 1043264, 30982, '<td valign="top">Ha!  Excellent light and shadow play.  And a great title!</td>', 'Ha!  Excellent light and shadow play.  And a great title!', '2012-12-06 21:16:52.000000', NULL, 1),
(6925352, 1043085, 30982, '<td valign="top">Stunning.  Must have been quite nice to have been there to witness it!</td>', 'Stunning.  Must have been quite nice to have been there to witness it!', '2012-12-06 21:17:07.000000', NULL, 1),
(6925353, 1042930, 30982, '<td valign="top">Love the muted approach to the toning/presentation, and the oddness of the person jumping is a nice change of pace from the usual scenery shot.</td>', 'Love the muted approach to the toning/presentation, and the oddness of the person jumping is a nice change of pace from the usual scenery shot.', '2012-12-06 21:17:43.000000', NULL, 1),
