(6926525, 1043323, 10785, '<td valign="top">Love the pastel hues! Nice and sharp enough to see the detailed texture in the grasses.</td>', 'Love the pastel hues! Nice and sharp enough to see the detailed texture in the grasses.', '2012-12-07 20:55:55.000000', NULL, 1),
(6926526, 1042876, 10785, '<td valign="top">So very crisp!</td>', 'So very crisp!', '2012-12-07 20:56:28.000000', NULL, 1),
