(6926533, 1043307, 10785, '<td valign="top">A great scene. Wonderful capture. I am seeing this as a touch soft and not quite sharp, possibly from the lens quality, or from being zoomed in at the far end. Perhaps a 1/2 stop overexposed showing up in the highlights on the grasses.</td>', 'A great scene. Wonderful capture. I am seeing this as a touch soft and not quite sharp, possibly from the lens quality, or from being zoomed in at the far end. Perhaps a 1/2 stop overexposed showing up in the highlights on the grasses.', '2012-12-07 20:59:19.000000', NULL, 1),
(6926534, 1042976, 10785, '<td valign="top">Nicely symmetrical! I didn''t notice the flag until later.</td>', 'Nicely symmetrical! I didn''t notice the flag until later.', '2012-12-07 20:59:59.000000', NULL, 1),
(6926535, 1042457, 10785, '<td valign="top">Nice mood.</td>', 'Nice mood.', '2012-12-07 21:00:14.000000', NULL, 1),
