INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6926539, 1043291, 10785, '<td valign="top">Nice and sharp with great exposure!</td>', 'Nice and sharp with great exposure!', '2012-12-07 21:03:36.000000', NULL, 1),
(6926541, 1042601, 10785, '<td valign="top">Very good technical work with good sharpness and color. Nice exposure. I think compositionally it needs some work. I think you are too close to be in rule of thirds. The focal point seems to be the silo which is in the center of the frame. So either get closer and use a vantage point looking up, or back up and make better use of rule of thirds. You did very well to keep that horizon below the middle.</td>', 'Very good technical work with good sharpness and color. Nice exposure. I think compositionally it needs some work. I think you are too close to be in rule of thirds. The focal point seems to be the silo which is in the center of the frame. So either get closer and use a vantage point looking up, or back up and make better use of rule of thirds. You did very well to keep that horizon below the middle.', '2012-12-07 21:07:06.000000', NULL, 1),
(6926543, 1043371, 10785, '<td valign="top">Neat light. I think you could have gotten a little closer, but I understand it is street photography.</td>', 'Neat light. I think you could have gotten a little closer, but I understand it is street photography.', '2012-12-07 21:09:29.000000', NULL, 1),
(6926544, 1043321, 10785, '<td valign="top">I think seagulls are constantly looking for happiness.</td>', 'I think seagulls are constantly looking for happiness.', '2012-12-07 21:10:11.000000', NULL, 1),
(6926545, 1043390, 10785, '<td valign="top">Cute little guy. I think this could have been a little tighter looking up or something! Cause there is that one distracting corner...</td>', 'Cute little guy. I think this could have been a little tighter looking up or something! Cause there is that one distracting corner...', '2012-12-07 21:12:12.000000', NULL, 1),
(6926546, 1043001, 10785, '<td valign="top">I think this suffers from white balance issues. It is very blue.</td>', 'I think this suffers from white balance issues. It is very blue.', '2012-12-07 21:13:08.000000', NULL, 1),
(6926547, 1042098, 10785, '<td valign="top">I really think you should have included the whole alley on the left.</td>', 'I really think you should have included the whole alley on the left.', '2012-12-07 21:14:21.000000', NULL, 1),
(6926560, 1043126, 65234, '<td valign="top">That''s gotta'' be Miss Abbey :-))) Very nice portrait.<br/> <br/>edit to fix spelling of her name.  D''oh!<br/><br/><i>Message edited by author 2012-12-08 07:15:49.</i></td>', 'That''s gotta'' be Miss Abbey :-))) Very nice portrait. edit to fix spelling of her name.  D''oh!', '2012-12-07 21:42:03.000000', '2012-12-08 07:15:49.000000', 1),
(6926561, 1042744, 65234, '<td valign="top">Amazing light! Beautifully captured.</td>', 'Amazing light! Beautifully captured.', '2012-12-07 21:45:13.000000', NULL, 1),
(6926562, 1043345, 65234, '<td valign="top">OK, you got a dramatically better shot than anything I got out there!  Love the pose; so dynamic!</td>', 'OK, you got a dramatically better shot than anything I got out there!  Love the pose; so dynamic!', '2012-12-07 21:45:47.000000', NULL, 1),
(6926565, 1042196, 65234, '<td valign="top">Stunning!  Absolutely gorgeous abstract with so much to wonder about.  There are stories to be told here.</td>', 'Stunning!  Absolutely gorgeous abstract with so much to wonder about.  There are stories to be told here.', '2012-12-07 21:47:27.000000', NULL, 1),
(6926566, 1043267, 65234, '<td valign="top">Amazing capture!  The light, DOF, bit of motion blur ... all perfect.  This one just blows me away.</td>', 'Amazing capture!  The light, DOF, bit of motion blur ... all perfect.  This one just blows me away.', '2012-12-07 21:48:57.000000', NULL, 1),
(6926567, 1041485, 83313, '<td valign="top">What a great portrait! It tells me so much about what this woman does and her passion for it.</td>', 'What a great portrait! It tells me so much about what this woman does and her passion for it.', '2012-12-07 21:49:05.000000', NULL, 1),
(6926568, 1043210, 65234, '<td valign="top">On the way to Mordor. Wonderfully textured landscape.</td>', 'On the way to Mordor. Wonderfully textured landscape.', '2012-12-07 21:49:54.000000', NULL, 1),
