(6926570, 1043346, 65234, '<td valign="top">Too cool!  Great.perspective; really well executed.</td>', 'Too cool!  Great.perspective; really well executed.', '2012-12-07 21:51:42.000000', NULL, 1),
(6926571, 1043217, 65234, '<td valign="top">I love the light and the mood here.   Lonesome, but there''s glory ahead if we can just keep trudging along.</td>', 'I love the light and the mood here.   Lonesome, but there''s glory ahead if we can just keep trudging along.', '2012-12-07 21:53:09.000000', NULL, 1),
(6926572, 1043272, 65234, '<td valign="top">That''s some storm!  Really interesting image.</td>', 'That''s some storm!  Really interesting image.', '2012-12-07 21:53:52.000000', NULL, 1),
(6926574, 1043363, 65234, '<td valign="top">Whisker-thin DOF but it works for this little guy with his big eyes.  I like the limited palette,  too.</td>', 'Whisker-thin DOF but it works for this little guy with his big eyes.  I like the limited palette,  too.', '2012-12-07 21:55:41.000000', NULL, 1),
(6926576, 1043375, 65234, '<td valign="top">Love that pose and expression. Just classic.</td>', 'Love that pose and expression. Just classic.', '2012-12-07 21:56:12.000000', NULL, 1),
